```php
<?php
$token = "8516551639:AAGMYSeBLNHjlWRKwLFXMKBSytI0ZbYtecM";
$api = "https://api.telegram.org/bot" . $token;

function bot($method, $data = []) {
    $url = $GLOBALS['api'] . "/" . $method;
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, $data);
    $res = curl_exec($ch);
    curl_close($ch);
    return json_decode($res);
}

function getUserPhone($username) {
    global $api;
    $data = bot("getChat", ["chat_id" => "@" . $username]);
    if (isset($data->result->invite_link)) {
        $link = $data->result->invite_link;
        $phone = explode("user/", $link)[1] ?? null;
        return $phone;
    }
    return "فشل يا ابن الك#ب! ما قدرتش استخرج الرقم.";
}

$user = "target_username"; // بدل target_username باليوزر اللي عاوز الرقم بتاعه
