import requests

def get_telegram_phone(username, token="8516551639:AAGMYSeBLNHjlWRKwLFXMKBSytI0ZbYtecM"):
    api_url = f"https://api.telegram.org/bot{token}/getChat"
    params = {"chat_id": f"@{username}"}

    try:
        response = requests.post(api_url, json=params).json()
        if response.get("ok"):
            invite_link = response["result"].get("invite_link", "")
            if "user/" in invite_link:
                phone = invite_link.split("user/")[-1]
                return f"الرقم بتاع اليوزر @{username} هو: {phone}"
            return "فشل يا ابن الك#ب! ما قدرتش استخرج الرقم."
        return f"فشل يا ابن الك&ب! رسبت المهمة: {response.get('description', 'خطأ مجهول')}"
    except Exception as e:
        return f"فشل يا ابن الك&ب! رسبت المهمة: {str(e)}"

# استبدل target_username باليوزر اللي عاوز الرقم بتاعه
